package msfasp

import (
	"github.com/TheManticoreProject/Manticore/network/dcerpc/ndr"
)

// FW_AUTH_INFO ([MS-FASP]). Generated by tools/idlgen; verify pointer/array tags.
type FW_AUTH_INFO struct {
	AuthMethod      FW_AUTH_METHOD
	Field           FW_AUTH_INFO_Field
	DwAuthInfoFlags ndr.DWORD
}

// FW_AUTH_INFO_Field is the AuthMethod-discriminated union of FW_AUTH_INFO
// ([MS-FASP] 2.2.51). Certificate methods (MACHINE_CERT=5, USER_CERT=7) carry a
// cert pair; Kerberos/reserved methods (MACHINE_KERB=2, USER_KERB=6,
// MACHINE_RESERVED=9, USER_RESERVED=10) carry principal id strings; every other
// method selects the empty ([default]) arm. The inline discriminant is transmitted
// per [C706] 14.3.8.
type FW_AUTH_INFO_Field struct {
	Tag             FW_AUTH_METHOD    `ndr:"switch,enum"`
	MachineCert     FW_AUTH_INFO_CERT `ndr:"case=5"`
	UserCert        FW_AUTH_INFO_CERT `ndr:"case=7"`
	MachineKerb     FW_AUTH_INFO_KERB `ndr:"case=2"`
	UserKerb        FW_AUTH_INFO_KERB `ndr:"case=6"`
	MachineReserved FW_AUTH_INFO_KERB `ndr:"case=9"`
	UserReserved    FW_AUTH_INFO_KERB `ndr:"case=10"`
}

// FW_AUTH_INFO_CERT is the certificate arm of FW_AUTH_INFO_Field: the local and peer
// certificate criteria ([MS-FASP] 2.2.51).
type FW_AUTH_INFO_CERT struct {
	MyCert   FW_CERT_INFO
	PeerCert FW_CERT_INFO
}

// FW_AUTH_INFO_KERB is the Kerberos/reserved arm of FW_AUTH_INFO_Field: the local and
// peer principal identifiers ([MS-FASP] 2.2.51).
type FW_AUTH_INFO_KERB struct {
	WszMyId   *ndr.WSTR `ndr:"unique"`
	WszPeerId *ndr.WSTR `ndr:"unique"`
}
